SELECT status AS status, COUNT(1) AS count FROM target_mgmt WHERE deleted = 0
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY status

SELECT evaluator_type AS evaluatorType, COUNT(1) AS count FROM target_mgmt WHERE deleted = 0
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY evaluator_type

SELECT score_type AS scoreType, COUNT(1) AS count FROM target_mgmt WHERE deleted = 0
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY score_type

SELECT total_score AS score, COUNT(1) AS count FROM target_mgmt WHERE deleted = 0
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY score
